36	using NodeFilter = std::function<bool(const Node &)>;
37	using GraphFilter = std::function<bool(const Node &, const char_t *, const ComputeGraphPtr &)>;
38	enum class TopoSortingMode : int32_t {
39	  kBFS = 0,
40	  kDFS,
