69	   * 递归的获取当前图和其子图的节点合集
70	   * @return 有序的节点合集，按照如下顺序返回
71	   * {node0, node1, {subgraph_node0, {sub_subgraph_node0, ..., sub_subgraph_noden}... ,subgraph_noden}, ... ,noden}
72	   */
73	  Vistor<NodePtr> GetAllNodes() const;
74	  std::vector<Node *> GetAllNodesPtr() const;
75	  // is_unknown_shape: false, same with GetAllNodes func
76	  // is_unknown_shape: true, same with GetDirectNodes func
77	  Vistor<NodePtr> GetNodes(const bool is_unknown_shape) const;
78	  Vistor<NodePtr> GetNodes(const bool is_unknown_shape, const NodeFilter &node_filter,
